import{z as r,x as B,o as l,c as d,q as o,j as n,D as a,d as E,s as p,S as i,b as A}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"Apple MLX","description":"","frontmatter":{"title":"Apple MLX","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mlx-apple.md","filePath":"llm/mlx-apple.md","lastUpdated":1791063341000}'),s={name:"llm/mlx-apple.md"};function m(D,e,M,P,c,C){const t=B("Mermaid");return l(),d("div",null,[e[2]||(e[2]=o('<h1 id="apple-mlx" tabindex="-1">Apple MLX <a class="header-anchor" href="#apple-mlx" aria-label="Permalink to &quot;Apple MLX&quot;">​</a></h1><div class="epigraph"><p>统一内存让权重、KV 与激活住在同一块 DRAM 里：没有 PCIe 拷贝，但屋顶线换成了内存控制器与 GPU/ANE 能同时咬多少带宽。</p><footer>—— Hannun 等，MLX 框架；Apple Silicon 统一内存是硬件前提</footer></div><p><a href="/llm/openvino">上一课</a>在 Intel 上讲共享内存。Apple Silicon 把 CPU、GPU 做成统一内存（UMA）：MLX 用这点做数组框架，延迟求值、在 GPU 上跑 Transformer。llama.cpp 的 Metal 后端是另一条路径，见 <a href="/llm/llamacpp">llama.cpp</a>。本课写 MLX 的差：Python 研究友好、统一内存上 <em>驻留策略简化</em>、以及 decode 仍被内存带宽绑住——只是没有 PCIe 那一项。不把某一 M 系列芯片的 GB/s 写成科学常数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CUDA 服务的加载是盘 → 主机 → HBM。<a href="/llm/weight-loading-streaming">权重加载</a>的 PCIe 在 Mac 上不存在同一形态：GPU 直接看统一内存中的数组。缺口是：程序员容易以为「没有拷贝 = 没有带宽墙」。decode 每步仍要扫 \\(W+\\mathrm{KV}\\)，墙是 DRAM 控制器。统一内存上 CPU 与 GPU 争同一带宽，一边 Python 预处理、一边 GPU decode，会互相伤害。</p><p>量化（4-bit）同样关键：笔记本级 DRAM 容量是容量墙。MLX 的量化类型与 GGUF k-quant 不是同一码本，质量数字不可直接比。</p><p><span class="marginnote">统一内存可以类比办公方式：独立显卡像「车间自带仓库」，CPU 和 GPU 各管各的仓库，要共享材料就得开车搬运（PCIe 拷贝）；统一内存像「全公司共用一个大仓库」，GPU 直接在架子上取料，省掉了搬运工。但共用仓库也意味着通道只有一条——大家同时取料就会排队，这正是下文「CPU 与 GPU 争带宽」的由来。</span></p><p><span class="marginnote">ANE（神经引擎）与 GPU 不是自动可互换。MLX 主路径是 GPU；把算子下沉 ANE 有形状限制，LLM decode 不总适合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用 MLX 实现或社区 LLM 包：权重以框架格式或转换脚本进统一内存，generate 循环在框架内。批处理 \\(B\\gt 1\\) 在本地聊天少见；若做，UMA 上加大 \\(B\\) 仍摊权重，拐点逻辑同前，只是峰值不同。与 Python 互操作：大数组应保持 MLX 端，避免 <code>numpy()</code> 隐式拷到 CPU 再拷回。流式 detokenize 仍在 CPU，注意不要每 token 触发大同步。</p>',10)),(l(),n(i,null,{default:a(()=>[p(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%9D%83%E9%87%8D%E5%9C%A8%E7%BB%9F%E4%B8%80%E5%86%85%E5%AD%98%22%5D%20--%3E%20GPU%5B%22Metal%20GPU%20%E6%89%AB%20W%2BKV%22%5D%0A%20%20KV%5B%22KV%20%E5%90%8C%E4%B8%80%E5%9D%97%20DRAM%22%5D%20--%3E%20GPU%0A%20%20CPU%5B%22CPU%20%E5%88%86%E8%AF%8D%20%2F%20%E9%87%87%E6%A0%B7%E8%BE%85%E5%8A%A9%22%5D%20--%3E%20BUS%5B%22%E4%BA%89%E7%94%A8%E5%86%85%E5%AD%98%E5%B8%A6%E5%AE%BD%22%5D%0A%20%20GPU%20--%3E%20BUS%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=A("h2",{id:"机制",tabindex:"-1"},[E("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=A("p",null,"UMA 消灭设备拷贝，不消灭访存能量与带宽。Horowitz 的 DRAM 能量项仍在。研究迭代（改模型、立刻跑）是 MLX 的强项；多租户 SLA 不是——没有 HBM 池与成熟的连续批生态可与 vLLM 对标。选择 MLX 是为了本地与研究，不是把数据中心服务搬到 Mac Studio 就结束会计。",-1)),(l(),n(i,null,{default:a(()=>[p(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20CMP%5B%22decode%20%E6%AF%8F%E6%AD%A5%E7%9A%84%E5%8F%96%E6%95%B0%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20CUDA%5B%22CUDA%20%E6%9C%8D%E5%8A%A1%E5%99%A8%EF%BC%9A%E7%9B%98%E5%88%B0%E4%B8%BB%E6%9C%BA%E5%88%B0%20HBM%22%5D%0A%20%20CMP%20--%3E%20MAC%5B%22Mac%20UMA%EF%BC%9A%E6%9D%83%E9%87%8D%E4%B8%8E%20KV%20%E5%90%8C%E4%B8%80%E5%9D%97%20DRAM%22%5D%0A%20%20CUDA%20--%3E%20C1%5B%22PCIe%20%E6%8B%B7%E8%B4%9D%E6%98%AF%E4%B8%80%E9%81%93%E9%A2%9D%E5%A4%96%E7%9A%84%E5%A2%99%22%5D%0A%20%20MAC%20--%3E%20M1%5B%22%E6%97%A0%E6%8B%B7%E8%B4%9D%EF%BC%8C%E4%BD%86%20DRAM%20%E6%8E%A7%E5%88%B6%E5%99%A8%E6%98%AF%E5%94%AF%E4%B8%80%E7%9A%84%E5%A2%99%22%5D%0A%20%20C1%20--%3E%20SAME%5B%22%E5%85%B1%E5%90%8C%E7%82%B9%EF%BC%9A%E6%AF%8F%E6%AD%A5%E9%83%BD%E8%A6%81%E6%89%AB%E4%B8%80%E9%81%8D%E6%9D%83%E9%87%8D%E5%8A%A0%20KV%22%5D%0A%20%20M1%20--%3E%20SAME%0A%20%20SAME%20--%3E%20TP%5B%22token%20%E9%80%9F%E5%BA%A6%E4%B8%8A%E9%99%90%E7%BA%A6%E7%AD%89%E4%BA%8E%E5%B8%A6%E5%AE%BD%E9%99%A4%E4%BB%A5%E6%AF%8F%20token%20%E5%AD%97%E8%8A%82%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=o('<p><span class="marginnote">「没有拷贝不等于没有带宽墙」可以用数字感受：4-bit 量化的 7B 模型权重约 4 GB，decode 每生成一个 token 都要把全部权重读一遍。假设内存带宽 100 GB/s，粗略上限就是 100 ÷ 4 ≈ 25 token/s——这就是本地聊天「够用但不飞快」的物理原因，跟软件写得好不好关系不大。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要用 MLX 的 eager 研究脚本当生产多用户引擎。不要把 Metal 与 CUDA FA 的加速比横比而不钉 \\(n,B\\)。下一课：浏览器里的 WebGPU，连 Python 都没有。</p><p><span class="marginnote">术语翻译：eager（急切执行）就是「写一行算一行」，像做菜时切一样炒一样；MLX 默认「延迟求值」，先把整张做法记下来，到 <code>eval</code> 时一口气开火——好处是框架能合并操作、少搬数据。初学者常忘了显式求值，以为自己已经算完了，一取结果才发现还在排队。</span></p><p>出处：MLX 项目（Hannun 等）；Apple Silicon 统一内存硬件文档。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MLX 利用 UMA：无 PCIe 拷贝，decode 仍绑 DRAM 带宽。</li><li>CPU 与 GPU 争用同一总线；预处理要让路。</li><li>量化码本与 GGUF 不同，质量分开测。</li><li>适合本地与研究，不是数据中心连续批。</li><li>避免无意义的 <code>numpy()</code> 往返。</li><li>下一课：WebGPU 推理。</li><li>出处：MLX；Apple Silicon 统一内存。</li></ul>',7))])}const u=r(s,[["render",m]]);export{h as __pageData,u as default};
